	private JPanel logSection(BossmanData.Rung r)
	{
		JPanel p = card();
		p.add(sectionTitle("Collection Log"));
		int kc = rules.rungKc(r);
		boolean any = false;
		for (BossmanData.GatingItem gi : r.log.gatingItems)
		{
			if (rules.isMeme(gi))
			{
				continue;
			}
			any = true;
			boolean have = rules.isLogItemUnlocked(gi);
			boolean bl = rules.isBacklogged(r, gi.item);
			JPanel row = logRow(gi.ids, (have ? "[x] " : "[ ] ") + gi.item, "Drop Rate: " + gi.rate + (bl && !have ? " - in backlog" : ""),
				have ? OK : (bl ? MUTED : Color.WHITE), MUTED);
			attachMenu(row, r, gi.item, gi.ids, have, true);
			p.add(row);
		}
		// gating pets/jars sit with the other gating items
		for (BossmanData.DebtItem d : r.log.debtPetsJars)
		{
			if (!rules.isDebtItemGating(d))
			{
				continue;
			}
			any = true;
			boolean have = rules.isDebtItemUnlocked(d);
			boolean bl = rules.isBacklogged(r, d.item);
			JPanel row = logRow(d.ids, (have ? "[x] " : "[ ] ") + d.item, "Drop Rate: " + d.rate + (bl && !have ? " - in backlog" : ""),
				have ? OK : (bl ? MUTED : Color.WHITE), MUTED);
			attachMenu(row, r, d.item, d.ids, have, true);
			p.add(row);
		}
		if (!any)
		{
			p.add(wrapped(r.log.gatingItems.isEmpty()
				? "This boss has no collection log; the first kill completes it."
				: "Nothing here gates this boss (all optional); the first kill completes it.", MUTED, 160));
		}
		return p;
	}

	/** Items that never gate: pets, jars and log items rarer than the meme threshold, or optional in the data (mode-locked rewards). */
	private JPanel memeSection(BossmanData.Rung r)
	{
		List<BossmanData.GatingItem> memes = new ArrayList<>();
		for (BossmanData.GatingItem gi : r.log.gatingItems)
		{
			if (rules.isMeme(gi))
			{
				memes.add(gi);
			}
		}
		List<BossmanData.DebtItem> memePets = new ArrayList<>();
		for (BossmanData.DebtItem d : r.log.debtPetsJars)
		{
			if (rules.isMeme(d))
			{
				memePets.add(d);
			}
		}
		if (memes.isEmpty() && memePets.isEmpty())
		{
			return null;
		}
		JPanel p = card();
		p.add(sectionTitle("Optional Items"));
		for (BossmanData.GatingItem gi : memes)
		{
			boolean have = rules.isLogItemUnlocked(gi);
			String why = gi.optional && gi.note != null ? gi.note : "meme grind";
			JPanel row = logRow(gi.ids, (have ? "[x] " : "[ ] ") + gi.item, "Drop Rate: " + gi.rate + " - " + why, have ? OK : MUTED, MUTED);
			attachMenu(row, r, gi.item, gi.ids, have, false);
			p.add(row);
		}
		for (BossmanData.DebtItem d : memePets)
		{
			boolean have = rules.isDebtItemUnlocked(d);
			JPanel row = logRow(d.ids, (have ? "[x] " : "[ ] ") + d.item, "Drop Rate: " + d.rate + " - meme grind", have ? OK : MUTED, MUTED);
			attachMenu(row, r, d.item, d.ids, have, false);
			p.add(row);
		}
		return p;
	}

	/** The backlog: pets/jars whose option is off, plus anything moved here by hand. */
	private JPanel backlogSection(BossmanData.Rung r)
	{
		JPanel p = card();
		p.add(sectionTitle("Backlog"));
		boolean any = false;
		for (BossmanData.GatingItem gi : r.log.gatingItems)
		{
			if (rules.isBacklogged(r, gi.item) && !rules.isLogItemUnlocked(gi))
			{
				any = true;
				JPanel row = logRow(gi.ids, gi.item, "Drop Rate: " + gi.rate + " - moved here by hand", BAD, MUTED);
				attachMenu(row, r, gi.item, gi.ids, false, true);
				p.add(row);
			}
		}
		for (BossmanData.DebtItem d : r.log.debtPetsJars)
		{
			if (rules.isDebtItemUnlocked(d) || rules.isMeme(d))
			{
				continue;
			}
			// the option wins while it's off; a hand-backlogged entry stays in the ledger for when it's back on
			boolean auto = rules.isAutoBacklogged(d);
			if (!auto && !rules.isBacklogged(r, d.item))
			{
				continue;
			}
			any = true;
			boolean owed = rules.isDebtOwed(r, d);
			String note = !auto ? " - moved here by hand"
				: d.debtAtKc == null ? "" : (owed ? " - overdue since KC " : " - expected by KC ") + d.debtAtKc;
			JPanel row = logRow(d.ids, d.item, "Drop Rate: " + d.rate + note, !auto || owed ? BAD : Color.WHITE, MUTED);
			if (auto)
			{
				row.setToolTipText("Backlogged because " + (rules.isJar(d) ? "jars" : "pets") + " don't gate the ladder (setting)");
				attachWikiMenu(row, d.item, d.ids);
			}
			else
			{
				attachMenu(row, r, d.item, d.ids, false, true);
			}
			p.add(row);
		}
		if (!any)
		{
			p.add(wrapped("Nothing in the backlog for this boss.", MUTED, 160));
		}
		return p;
	}

	/** Client-property keys that describe a row to the shared context menu. */
	private static final String ROW_ITEM = "bm.item";
	private static final String ROW_IDS = "bm.ids";
	private static final String ROW_RUNG = "bm.rung";
	private static final String ROW_BACKLOGABLE = "bm.backlogable";
	/** set on unlock rows: the item id a "Re-lock" entry takes back */
	private static final String ROW_RELOCK = "bm.relock";

	/**
	 * One popup menu for every row. Swing hands show() the component that was clicked; we find the row it
	 * belongs to and build the entries for it on the spot. Saves allocating a menu per row per rebuild.
	 */
	private final javax.swing.JPopupMenu rowMenu = new javax.swing.JPopupMenu()
	{
		@Override
		public void show(java.awt.Component invoker, int x, int y)
		{
			java.awt.Component c = invoker;
			while (c != null && !(c instanceof JPanel && ((JPanel) c).getClientProperty(ROW_ITEM) != null))
			{
				c = c.getParent();
			}
			if (c == null)
			{
				return;
			}
			JPanel row = (JPanel) c;
			String item = (String) row.getClientProperty(ROW_ITEM);
			@SuppressWarnings("unchecked")
			List<Integer> ids = (List<Integer>) row.getClientProperty(ROW_IDS);
			BossmanData.Rung r = (BossmanData.Rung) row.getClientProperty(ROW_RUNG);
			removeAll();
			// Open Wiki is always the first entry, whatever else the row offers
			javax.swing.JMenuItem wiki = new javax.swing.JMenuItem("Open Wiki");
			wiki.setFont(FontManager.getRunescapeSmallFont());
			wiki.addActionListener(e -> net.runelite.client.util.LinkBrowser.browse(itemWikiUrl(item, ids)));
			add(wiki);
			if (r != null && Boolean.TRUE.equals(row.getClientProperty(ROW_BACKLOGABLE)))
			{
				boolean bl = rules.isBacklogged(r, item);
				javax.swing.JMenuItem mi = new javax.swing.JMenuItem(bl ? "Remove from Backlog" : "Move to Backlog");
				mi.setFont(FontManager.getRunescapeSmallFont());
				mi.addActionListener(e -> plugin.setBacklogged(r, item, !bl));
				add(mi);
			}
			Integer relockId = (Integer) row.getClientProperty(ROW_RELOCK);
			if (relockId != null)
			{
				javax.swing.JMenuItem relock = new javax.swing.JMenuItem("Re-lock");
				relock.setFont(FontManager.getRunescapeSmallFont());
				relock.addActionListener(e -> plugin.relock(relockId));
				add(relock);
			}
			super.show(invoker, x, y);
		}
	};

	/** The wiki link plus the backlog toggle (only while the item is still locked and gating). */
	private void attachMenu(JPanel row, BossmanData.Rung r, String item, List<Integer> ids, boolean have, boolean backlogable)
	{
		row.putClientProperty(ROW_RUNG, r);
		row.putClientProperty(ROW_BACKLOGABLE, backlogable && !have);
		attachWikiMenu(row, item, ids);
	}

	/** Right-click with only "Open Wiki" (unlock / still-locked rows). */
	private void attachWikiMenu(JPanel row, String item, List<Integer> ids)
	{
		row.putClientProperty(ROW_ITEM, item);
		row.putClientProperty(ROW_IDS, ids);
		installMenu(row, rowMenu);
	}

	private static String bossWikiUrl(BossmanData.Rung r)
	{
		return "https://oldschool.runescape.wiki/w/" + (r.wikiPage != null ? r.wikiPage : urlEncode(r.boss.replace(' ', '_')));
	}

	private static String itemWikiUrl(String item, List<Integer> ids)
	{
		if (ids != null && !ids.isEmpty())
		{
			return "https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=" + ids.get(0) + "&name=" + urlEncode(item);
		}
		return "https://oldschool.runescape.wiki/w/" + urlEncode(item.replace(' ', '_'));
	}

	private static String urlEncode(String s)
	{
		try
		{
			return java.net.URLEncoder.encode(s, "UTF-8");
		}
		catch (java.io.UnsupportedEncodingException e)
		{
			return s;
		}
	}

	/** Make the whole row (and its labels) open the menu on right-click. */
	private void installMenu(JPanel row, javax.swing.JPopupMenu menu)
	{
		row.setComponentPopupMenu(menu);
		for (java.awt.Component c : row.getComponents())
		{
			if (c instanceof javax.swing.JComponent)
			{
				((javax.swing.JComponent) c).setInheritsPopupMenu(true);
				if (c instanceof java.awt.Container)
				{
					for (java.awt.Component cc : ((java.awt.Container) c).getComponents())
					{
						if (cc instanceof javax.swing.JComponent)
						{
							((javax.swing.JComponent) cc).setInheritsPopupMenu(true);
						}
					}
				}
			}
		}
	}

	/** Wrapped text is laid out at this width and never reflowed wider, so long names wrap instead of clipping. */
	private static final int LOG_TEXT_WIDTH = 125;

	private JLabel wrapped(String text, Color color)
	{
		return wrapped(text, color, LOG_TEXT_WIDTH);
	}

	private JLabel wrapped(String text, Color color, int width)
	{
		JLabel l = new JLabel("<html><body style='width:" + width + "px'>" + escape(text) + "</body></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setAlignmentX(LEFT_ALIGNMENT);
		l.setMaximumSize(l.getPreferredSize());
		return l;
	}

	private JPanel logRow(List<Integer> ids, String title, String sub, Color titleColor, Color subColor)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		if (ids != null && !ids.isEmpty())
		{
			image(ids.get(0)).addTo(icon);
		}
		row.add(icon, BorderLayout.WEST);
		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		text.add(wrapped(title, titleColor));
		text.add(wrapped(Numbers.withCommas(sub), subColor));
		row.add(text, BorderLayout.CENTER);
		row.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		Dimension pref = row.getPreferredSize();
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Math.max(36, pref.height)));
		return row;
	}

	/** What this boss has unlocked for you, then what it still could. */
	private JPanel unlocksSection(BossmanData.Rung r)
	{
		JPanel p = card();
		java.util.Set<String> sources = new java.util.HashSet<>();
		for (String src : r.sources)
		{
			sources.add(src.toLowerCase(java.util.Locale.ROOT));
		}
		// collection-log items have their own section; keep them out of this one
		java.util.Set<Integer> logIds = new java.util.HashSet<>();
		for (BossmanData.GatingItem gi : r.log.gatingItems)
		{
			logIds.addAll(gi.ids);
		}
		for (BossmanData.DebtItem d : r.log.debtPetsJars)
		{
			logIds.addAll(d.ids);
		}
		for (BossmanData.Drop d : r.drops)
		{
			if (d.inLog)
			{
				logIds.addAll(d.ids);
			}
		}
		// unlocked by one of this boss's sources
		List<Ledger.Entry> mine = new ArrayList<>();
		java.util.Set<Integer> mineIds = new java.util.HashSet<>();
		for (Ledger.Entry en : plugin.getLedger().unlocks.values())
		{
			if (en.source != null && sources.contains(en.source.toLowerCase(java.util.Locale.ROOT)) && !logIds.contains(en.itemId))
			{
				mine.add(en);
				mineIds.add(en.itemId);
			}
		}
		int possible = 0;
		int unlockedHere = 0;
		int unlockedElsewhere = 0;
		List<BossmanData.Drop> locked = new ArrayList<>();
		for (BossmanData.Drop d : r.drops)
		{
			if (d.inLog)
			{
				continue; // already listed in the collection log section
			}
			possible++;
			if (d.ids.stream().anyMatch(mineIds::contains))
			{
				unlockedHere++;
			}
			else if (d.ids.stream().anyMatch(plugin.getLedger()::isUnlocked))
			{
				unlockedElsewhere++;
			}
			else
			{
				locked.add(d);
			}
		}
		// count every drop that's unlocked, wherever it came from, so the two numbers add up to the drop table
		p.add(sectionTitle("Unlocks (" + (unlockedHere + unlockedElsewhere) + "/" + possible + ")"));
		if (mine.isEmpty())
		{
			p.add(wrapped("Nothing unlocked from this boss yet.", MUTED, 160));
		}
		// same order as the drop table: commonest first (items without a known rate go last, in unlock order)
		mine.sort((a, b) -> Integer.compare(dropIndex(r, a.itemId), dropIndex(r, b.itemId)));
		for (Ledger.Entry en : mine)
		{
			String rate = rateFor(r, en.itemId);
			JPanel row = logRow(java.util.Collections.singletonList(en.itemId), "[x] " + en.name,
				(rate != null ? "Drop Rate: " + rate + " - " : "") + "KC " + (en.kc != null ? en.kc : "?"), OK, MUTED);
			row.putClientProperty(ROW_RELOCK, en.itemId);
			attachWikiMenu(row, en.name, java.util.Collections.singletonList(en.itemId));
			p.add(row);
		}
		if (unlockedElsewhere > 0)
		{
			p.add(wrapped(unlockedElsewhere + " more already unlocked from other sources.", MUTED, 160));
		}
		if (!locked.isEmpty())
		{
			p.add(Box.createVerticalStrut(6));
			p.add(subTitle("Still Locked (" + Numbers.format(locked.size()) + ")"));
			p.add(Box.createVerticalStrut(4));
			int shown = 0;
			for (BossmanData.Drop d : locked)
			{
				if (shown++ >= MAX_LOCKED_SHOWN)
				{
					p.add(label("... and " + (locked.size() - MAX_LOCKED_SHOWN) + " more", MUTED));
					break;
				}
				JPanel row = logRow(d.ids, "[ ] " + d.item, "Drop Rate: " + d.rate, Color.WHITE, MUTED);
				attachWikiMenu(row, d.item, d.ids);
				p.add(row);
			}
		}
		return p;
	}

	private int dropIndex(BossmanData.Rung r, int itemId)
	{
		for (int i = 0; i < r.drops.size(); i++)
		{
			if (r.drops.get(i).ids.contains(itemId))
			{
				return i;
			}
		}
		return Integer.MAX_VALUE;
	}

	private String rateFor(BossmanData.Rung r, int itemId)
	{
		for (BossmanData.Drop d : r.drops)
		{
			if (d.ids.contains(itemId))
			{
				return d.rate;
			}
		}
		return null;
	}

	private JPanel card()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		return p;
	}

	private JLabel subTitle(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(Color.WHITE);
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	private JLabel sectionTitle(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(WARN);
		l.setAlignmentX(LEFT_ALIGNMENT);
		l.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		return l;
	}

	private JLabel label(String text, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setHorizontalAlignment(SwingConstants.LEFT);
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	/** A drawn chevron, so the arrows match at any font and grey out when the button is disabled. */
	private static class ChevronIcon implements javax.swing.Icon
	{
		private final boolean left;

		ChevronIcon(boolean left)
		{
			this.left = left;
		}

		@Override
		public int getIconWidth()
		{
			return 8;
		}

		@Override
		public int getIconHeight()
		{
			return 10;
		}

		@Override
		public void paintIcon(java.awt.Component c, java.awt.Graphics g, int x, int y)
		{
			java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
			g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setStroke(new java.awt.BasicStroke(1.8f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
			g2.setColor(c.isEnabled() ? Color.WHITE : MUTED);
			int tip = left ? x + 2 : x + 6;
			int tail = left ? x + 6 : x + 2;
			g2.drawLine(tail, y + 1, tip, y + 5);
			g2.drawLine(tip, y + 5, tail, y + 9);
			g2.dispose();
		}
	}

	private JButton arrowButton(String text)
	{
		JButton b = smallButton("");
		b.setIcon(new ChevronIcon("<".equals(text)));
		b.setDisabledIcon(b.getIcon());
		b.setMargin(new java.awt.Insets(1, 7, 1, 7));
		return b;
	}

	private JButton smallButton(String text)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setMargin(new java.awt.Insets(1, 6, 1, 6));
		b.setFocusPainted(false);
		return b;
	}

	private static String escape(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

/*
 * Bossman Mode: reads Combat Achievement state straight from the game.
 *
 * The task list lives in the cache: one enum per tier (3981..3986) listing task structs, each struct carrying
 * the task's numeric id (param 1306) and title (param 1308). Completion is a bit-field across the
 * CA_TASK_COMPLETED_n varps: task n is bit n % 32 of varp n / 32, the same thing the in-game interface reads.
 * Everything here must run on the client thread.
 */
package com.bossman;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

class CombatTasks
{
	private static final Logger log = LoggerFactory.getLogger(CombatTasks.class);

	private static final int[] TIER_ENUMS = {3981, 3982, 3983, 3984, 3985, 3986};   // easy .. grandmaster
	private static final int PARAM_TASK_ID = 1306;
	private static final int PARAM_TASK_NAME = 1308;
	private static final int[] COMPLETED_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20,
	};
	private static final Set<Integer> COMPLETED_VARP_SET = new HashSet<>();

	static
	{
		for (int v : COMPLETED_VARPS)
		{
			COMPLETED_VARP_SET.add(v);
		}
	}

	private final Client client;
	/** task id → title, read once from the cache */
	private Map<Integer, String> names = Collections.emptyMap();
	private boolean warnedOutOfRange;

	CombatTasks(Client client)
	{
		this.client = client;
	}

	static boolean isCompletionVarp(int varpId)
	{
		return COMPLETED_VARP_SET.contains(varpId);
	}

	/** Load the task table from the cache if it hasn't been yet. Client thread. */
	private boolean ensureLoaded()
	{
		if (!names.isEmpty())
		{
			return true;
		}
		Map<Integer, String> out = new HashMap<>();
		for (int enumId : TIER_ENUMS)
		{
			EnumComposition tier = client.getEnum(enumId);
			if (tier == null)
			{
				continue;
			}
			for (int structId : tier.getIntVals())
			{
				StructComposition s = client.getStructComposition(structId);
				if (s == null)
				{
					continue;
				}
				String name = s.getStringValue(PARAM_TASK_NAME);
				if (name != null && !name.isEmpty())
				{
					out.put(s.getIntValue(PARAM_TASK_ID), name);
				}
			}
		}
		if (out.isEmpty())
		{
			log.debug("combat achievement enums not available yet");
			return false;
		}
		names = out;
		log.debug("loaded {} combat achievement tasks", out.size());
		return true;
	}

	/** Titles of every task the account has completed, per the game's own state. Client thread. Empty if the cache isn't readable yet. */
	Set<String> completedNames()
	{
		if (!ensureLoaded())
		{
			return Collections.emptySet();
		}
		int[] bits = new int[COMPLETED_VARPS.length];
		for (int i = 0; i < bits.length; i++)
		{
			bits[i] = client.getVarpValue(COMPLETED_VARPS[i]);
		}
		Set<String> done = new HashSet<>();
		for (Map.Entry<Integer, String> en : names.entrySet())
		{
			int id = en.getKey();
			if (id < 0 || id >= bits.length * 32)
			{
				if (!warnedOutOfRange)
				{
					warnedOutOfRange = true;
					log.warn("combat task id {} is past the {} completion varps known to the plugin; newer tasks can't be read", id, bits.length);
				}
				continue;
			}
			if (isComplete(bits, id))
			{
				done.add(en.getValue());
			}
		}
		return done;
	}

	/** Titles of every task in the game's table (empty until the cache is readable). Client thread. */
	Set<String> allNames()
	{
		return ensureLoaded() ? new HashSet<>(names.values()) : Collections.emptySet();
	}

	/** Task {@code id} is bit id % 32 of completion word id / 32. */
	static boolean isComplete(int[] bits, int id)
	{
		int word = id / 32;
		return id >= 0 && word < bits.length && ((bits[word] >>> (id % 32)) & 1) == 1;
	}
}

/*
 * Bossman Mode: why an item is usable without a boss drop.
 */
package com.bossman;

enum FreeKind
{
	/** base tier of the wiki Tool page, and basic containers empty or holding water or soil */
	TOOL,
	/** gear that only gets you to a boss: slayer access gear, keys and totems, grapple, rope */
	ACCESS,
	/** consumable slayer tools a task monster needs to be finished (rock hammer, bag of salt, ...) */
	SLAYER,
	/** made or handed out inside a boss's area for use there (Wintertodt's potions, raid supplies, Gauntlet gear) */
	BOSS_CRAFTABLE,
	/** Old School bonds, so membership can be bought */
	BOND
}

/*
 * Bossman Mode: reads the game's kill-count messages. No client state, so the real message wording is tested in
 * KcMessagesTest.
 */
package com.bossman;

import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class KcMessages
{
	/** A KC the game reported: stored under {@code key} (the source, or "Source (Mode)" for a raid mode), credited to {@code source}. */
	static final class Kc
	{
		final String source;
		final String key;
		final int count;

		Kc(String source, String key, int count)
		{
			this.source = source;
			this.key = key;
			this.count = count;
		}
	}

	/**
	 * "Your completed Chambers of Xeric count is: 12", "Your completed Theatre of Blood: Hard Mode count is: 3".
	 * Matched before {@link #KC}, which would otherwise read "completed Chambers of Xeric" as the name.
	 */
	private static final Pattern RAID = Pattern.compile("Your completed (.+?) count is:? ?([\\d,]+)", Pattern.CASE_INSENSITIVE);
	/**
	 * "Your Vorkath kill count is: 14", "Your Gauntlet completion count is: 2", "Your Lunar Chest count is: 5",
	 * "Your Barrows chest count is: 3" (the name keeps "chest"; aliases map "barrows chest" to Barrows).
	 */
	private static final Pattern KC = Pattern.compile("Your (.+?) (?:kill |completion )?count is:? ?([\\d,]+)", Pattern.CASE_INSENSITIVE);
	/** a raid mode after the raid's name: "...: Hard Mode", "... Challenge Mode" */
	private static final Pattern MODE = Pattern.compile("^(.+?)(?::\\s*|\\s+)((?:Challenge|Hard|Entry|Expert) Mode)$", Pattern.CASE_INSENSITIVE);

	private KcMessages()
	{
	}

	/**
	 * The KC in a game message, or null if it has none or names no source.
	 *
	 * @param canonicalSource name as the game writes it → the source it counts (null if none)
	 */
	static Kc parse(String message, Function<String, String> canonicalSource)
	{
		Matcher m = RAID.matcher(message);
		if (!m.find())
		{
			m = KC.matcher(message);
			if (!m.find())
			{
				return null;
			}
		}
		int n;
		try
		{
			n = Integer.parseInt(m.group(2).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
		// the game writes names with non-breaking spaces at times
		String name = m.group(1).replace(' ', ' ').trim();
		String mode = null;
		Matcher mm = MODE.matcher(name);
		if (mm.matches())
		{
			name = mm.group(1).trim();
			mode = capitalise(mm.group(2));
		}
		String source = canonicalSource.apply(name);
		if (source == null)
		{
			return null;
		}
		return new Kc(source, mode == null ? source : source + " (" + mode + ")", n);
	}

	private static String capitalise(String mode)
	{
		String w = mode.trim().toLowerCase(java.util.Locale.ROOT);
		return Character.toUpperCase(w.charAt(0)) + w.substring(1, w.indexOf(' ')) + " Mode";
	}
}

/*
 * Bossman Mode: the ruleset, as pure queries over the bundled data, the ledger and the config.
 * Nothing here mutates anything. The rung and log queries are safe from any thread (the ledger's collections are
 * concurrent); isAllowed and freeKind canonicalize item ids, which reads the item cache, so call those on the client
 * thread.
 */
package com.bossman;

import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.Set;
import java.util.function.Supplier;
import net.runelite.api.gameval.ItemID;

public class LadderRules
{
	/** What a rung still needs: gating items, gating pets/jars and (when they gate) combat tasks. */
	public static final class Progress
	{
		public final int have;
		public final int need;

		Progress(int have, int need)
		{
			this.have = have;
			this.need = need;
		}

		public boolean complete()
		{
			return have >= need;
		}
	}

	private final BossmanData data;
	private final BossmanModeConfig config;
	/** unnote / un-placeholder / worn → inventory id (ItemManager.canonicalize in the plugin) */
	private final IntUnaryOperator canonicalize;
	/** every id in an item's variation group: potion doses, jewellery charges, degraded and charged forms */
	private final IntFunction<Collection<Integer>> variations;
	private final Supplier<Ledger> ledger;
	/** an item a started quest on a boss's quest chain needs (canonical id) */
	private final IntPredicate questItem;
	/** lower-cased names of everything unlocked, for the pet/jar fallback; rebuilt when the ledger or its size changes */
	private Ledger namesOf;
	private int namesSize = -1;
	private Set<String> unlockedNames = new HashSet<>();

	public LadderRules(BossmanData data, BossmanModeConfig config, IntUnaryOperator canonicalize,
		IntFunction<Collection<Integer>> variations, Supplier<Ledger> ledger, IntPredicate questItem)
	{
		this.data = data;
		this.config = config;
		this.canonicalize = canonicalize;
		this.variations = variations;
		this.ledger = ledger;
		this.questItem = questItem;
	}

	/**
	 * Unlocked by a boss, free under the Tool / access / bond rules, a shop pack whose contents all are, food cooked from
	 * an allowed raw fish or meat, or needed by a started quest. Another form of an unlocked item counts too: Prayer potion(3) once Prayer potion(4) dropped, a
	 * degraded Dharok's helm, an uncharged Trident. Free items count only as themselves: RuneLite groups a raid's
	 * overload with the real one and the Gauntlet's crystal armour with the real set. Client thread.
	 */
	public boolean isAllowed(int itemId)
	{
		int id = canonicalize.applyAsInt(itemId);
		return isAllowed(ledger.get(), id) || questItem.test(id);
	}

	/** Allowed only while the quest that needs it is in progress. Client thread. */
	public boolean isQuestItemOnly(int itemId)
	{
		int id = canonicalize.applyAsInt(itemId);
		return questItem.test(id) && !isAllowed(ledger.get(), id);
	}

	private boolean isAllowed(Ledger l, int id)
	{
		if (l.isUnlocked(id) || freeKindOfCanonical(id) != null)
		{
			return true;
		}
		for (int v : variations.apply(id))
		{
			if (v != id && l.isUnlocked(v))
			{
				return true;
			}
		}
		if (config.cookedFood())
		{
			for (int raw : data.getCookedFrom().getOrDefault(id, Collections.emptyList()))
			{
				if (isAllowed(l, raw))
				{
					return true;
				}
			}
		}
		List<Integer> contents = data.getSources().itemPacks.get(id);
		if (contents == null || contents.isEmpty())
		{
			return false;
		}
		for (int c : contents)
		{
			if (!isAllowed(l, c))
			{
				return false;
			}
		}
		return true;
	}

	/** Why the item is free, if it is under a rule that is switched on, else null. Client thread. */
	public FreeKind freeKind(int itemId)
	{
		return freeKindOfCanonical(canonicalize.applyAsInt(itemId));
	}

	private FreeKind freeKindOfCanonical(int id)
	{
		if (id == ItemID.OSRS_BOND)
		{
			return config.unlockBond() ? FreeKind.BOND : null;
		}
		FreeKind kind = data.getFreeItems().get(id);
		if (kind == null)
		{
			return null;
		}
		switch (kind)
		{
			case TOOL:
				return config.freeTools() ? kind : null;
			case ACCESS:
				return config.freeAccessGear() ? kind : null;
			case SLAYER:
				return config.freeSlayerTools() ? kind : null;
			case BOSS_CRAFTABLE:
				return config.freeBossCraftables() ? kind : null;
			default:
				return kind;
		}
	}

	/**
	 * Optional: never gates the ladder. Either marked so in the data (mode-locked, a KC-milestone reward) or a
	 * "meme grind": 1 in the configured threshold or rarer.
	 */
	public boolean isMeme(BossmanData.GatingItem gi)
	{
		return gi.optional || (gi.denominator != null && gi.denominator >= config.memeThreshold());
	}

	/** A pet or jar at the meme threshold or rarer: optional, so it never gates and never goes to the backlog. */
	public boolean isMeme(BossmanData.DebtItem d)
	{
		// debtAtKc is the rate's denominator
		return d.debtAtKc != null && d.debtAtKc >= config.memeThreshold();
	}

	public boolean isJar(BossmanData.DebtItem d)
	{
		return d.item != null && d.item.toLowerCase(Locale.ROOT).startsWith("jar of");
	}

	/** Pets/jars gate only when the matching option is on, and never when they are meme grinds. */
	public boolean isDebtItemGating(BossmanData.DebtItem d)
	{
		return !isMeme(d) && (isJar(d) ? config.jarsGate() : config.petsGate());
	}

	/**
	 * In the backlog because its option is off. Worked out from the config on every call and never written to the
	 * ledger, so toggling the option keeps the pets and jars the player backlogged by hand.
	 */
	public boolean isAutoBacklogged(BossmanData.DebtItem d)
	{
		return !isMeme(d) && !isDebtItemGating(d);
	}

	/** Past the KC where the pet/jar is expected (false when its rate is unknown or it is a meme grind). */
	public boolean isDebtOwed(BossmanData.Rung r, BossmanData.DebtItem d)
	{
		return d.debtAtKc != null && !isMeme(d) && rungKc(r) >= d.debtAtKc;
	}

	public boolean isDebtItemUnlocked(BossmanData.DebtItem d)
	{
		return isDebtItemUnlocked(ledger.get(), d);
	}

	private boolean isDebtItemUnlocked(Ledger l, BossmanData.DebtItem d)
	{
		// pets are often recorded under a different id (follower vs inventory form); fall back to the name
		return anyUnlocked(l, d.ids) || (d.item != null && unlockedNames(l).contains(d.item.toLowerCase(Locale.ROOT)));
	}

	private synchronized Set<String> unlockedNames(Ledger l)
	{
		if (l != namesOf || l.unlocks.size() != namesSize)
		{
			Set<String> names = new HashSet<>();
			for (Ledger.Entry en : l.unlocks.values())
			{
				if (en.name != null)
				{
					names.add(en.name.toLowerCase(Locale.ROOT));
				}
			}
			namesOf = l;
			namesSize = l.unlocks.size();
			unlockedNames = names;
		}
		return unlockedNames;
	}

	public boolean isLogItemUnlocked(BossmanData.GatingItem gi)
	{
		return anyUnlocked(ledger.get(), gi.ids);
	}

	private static boolean anyUnlocked(Ledger l, List<Integer> ids)
	{
		for (int id : ids)
		{
			if (l.isUnlocked(id))
			{
				return true;
			}
		}
		return false;
	}

	public static String backlogKey(BossmanData.Rung r, String item)
	{
		return r.boss + "|" + item;
	}

	public boolean isBacklogged(BossmanData.Rung r, String item)
	{
		return ledger.get().backlog.contains(backlogKey(r, item));
	}

	public boolean isCaGating()
	{
		return config.caGate();
	}

	public boolean isCaDone(BossmanData.CaTask t)
	{
		return ledger.get().isCaDone(t.name);
	}

	/**
	 * The rung's KC: its own KC source if it names one (Lunar Chest for the Moons, the Sire for the Sire and Unsired),
	 * else the sum over its sources (all three Dagannoth Kings). A raid's modes, counted apart by the game, add up.
	 */
	public int rungKc(BossmanData.Rung r)
	{
		Ledger l = ledger.get();
		if (r.kcSource != null)
		{
			return l.getKcAllModes(sourceKey(r.kcSource));
		}
		int total = 0;
		for (String s : r.sources)
		{
			total += l.getKcAllModes(sourceKey(s));
		}
		return total;
	}

	/** KC at each of the rung's sources, in data order (for rungs with more than one: the three Moons, the chest). */
	public Map<String, Integer> kcBySource(BossmanData.Rung r)
	{
		Ledger l = ledger.get();
		Map<String, Integer> out = new LinkedHashMap<>();
		for (String s : r.sources)
		{
			out.put(s, l.getKcAllModes(sourceKey(s)));
		}
		return out;
	}

	/** The key KC is stored under: the bundled spelling of the source (the ladder may write it differently). */
	private String sourceKey(String s)
	{
		String c = data.canonicalSource(s);
		return c != null ? c : s;
	}

	/** Have / need over everything that gates the rung; need is 0 when nothing does (then the first kill is the rung). */
	public Progress progress(BossmanData.Rung r)
	{
		Ledger l = ledger.get();
		int have = 0;
		int need = 0;
		for (BossmanData.GatingItem gi : r.log.gatingItems)
		{
			if (isMeme(gi) || l.backlog.contains(backlogKey(r, gi.item)))
			{
				continue;
			}
			need++;
			if (anyUnlocked(l, gi.ids))
			{
				have++;
			}
		}
		for (BossmanData.DebtItem d : r.log.debtPetsJars)
		{
			if (!isDebtItemGating(d) || l.backlog.contains(backlogKey(r, d.item)))
			{
				continue;
			}
			need++;
			if (isDebtItemUnlocked(l, d))
			{
				have++;
			}
		}
		if (config.caGate() && r.ca != null)
		{
			for (BossmanData.CaTask t : r.ca.list)
			{
				need++;
				if (l.isCaDone(t.name))
				{
					have++;
				}
			}
		}
		return new Progress(have, need);
	}

	public boolean isManuallyComplete(BossmanData.Rung r)
	{
		return ledger.get().manualComplete.contains(r.boss);
	}

	public boolean isRungComplete(BossmanData.Rung r)
	{
		if (isManuallyComplete(r))
		{
			return true;
		}
		if (r.isFirstKillOnly())
		{
			return rungKc(r) >= 1;
		}
		Progress p = progress(r);
		return p.need == 0 ? rungKc(r) >= 1 : p.complete();
	}

	/**
	 * The skilling boss the player chose to do first, until it is complete; otherwise the lowest incomplete rung, the
	 * boss the series is on. Null once the ladder is done. Side bosses (non-blocking: no log of their own, or a log
	 * shared with a bigger boss) never hold the ladder up.
	 */
	public BossmanData.Rung currentRung()
	{
		BossmanData.Rung focused = focusedRung();
		if (focused != null)
		{
			return focused;
		}
		for (BossmanData.Rung r : data.orderedRungs())
		{
			if (r.blocking && !isRungComplete(r))
			{
				return r;
			}
		}
		return null;
	}

	/** The skilling boss the player chose to do ahead of the ladder, while it is incomplete; else null. */
	public BossmanData.Rung focusedRung()
	{
		String boss = ledger.get().focus;
		if (boss == null)
		{
			return null;
		}
		for (BossmanData.Rung r : data.browsableRungs())
		{
			if (r.skilling && r.boss.equals(boss) && !isRungComplete(r))
			{
				return r;
			}
		}
		return null;
	}
}

/*
 * Bossman Mode: the unlock ledger. Every unlocked item with its provenance, per-source kill counts, rungs the
 * player marked complete by hand, the backlog and completed combat tasks. Persisted as JSON at the path
 * BossmanModePlugin.ledgerFile() gives (the plugin's data directory, <world type>-<account hash>/). All file access
 * goes through RuneLite's Filepath, which keeps it inside that directory.
 *
 * Mutated on the client thread, read on the Swing thread by the panel: every collection is concurrent so
 * a rebuild never trips over a write. Saving is the plugin's job (debounced); this class does the I/O and keeps
 * its own "has unsaved changes" flag, so one ledger's pending save can never be mistaken for another's.
 */
package com.bossman;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.atomic.AtomicBoolean;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Ledger
{
	private static final Logger log = LoggerFactory.getLogger(Ledger.class);

	public static final String KIND_DROP = "drop";
	public static final String KIND_RECEIPT = "receipt";
	public static final String KIND_DEFAULT = "default";
	public static final String KIND_CLOG = "clog";       // imported from the in-game collection log (obtained before the plugin)

	public static class Entry
	{
		public int itemId;
		public String name;
		public String kind;     // drop / receipt / default / clog
		public String source;   // boss or event name
		public Integer kc;      // KC at the source when it dropped
		public long time;       // epoch millis
		public String reason;   // why it unlocked when it wasn't a plain drop (receipt rule note, collection-log import)
	}

	/** item id → entry. Declared as Map so Gson can read a file holding nulls; {@link #normalize} makes it concurrent. */
	public Map<Integer, Entry> unlocks = new ConcurrentHashMap<>();
	/**
	 * KC key → kills seen. The key is the source name, or "Source (Mode)" for a raid mode the game counts on its own
	 * ("Chambers of Xeric (Challenge Mode)"); {@link #getKcAllModes} adds the modes up.
	 */
	public Map<String, Integer> kc = new ConcurrentHashMap<>();
	/** boss names of rungs the player marked complete by hand (no-log rungs like the Gemstone Crab) */
	public Set<String> manualComplete = ConcurrentHashMap.newKeySet();
	/** boss name of the skilling rung the player is doing before the ladder's next boss; null follows the ladder */
	public volatile String focus;
	/** collection-log items moved to the backlog by hand, as "boss|item" (they stop gating the ladder) */
	public Set<String> backlog = ConcurrentHashMap.newKeySet();
	/** completed combat task titles as {@link #caKey}s, synced from the game's completion varps */
	public Set<String> caDone = ConcurrentHashMap.newKeySet();
	/**
	 * sources whose KC the game reports in chat ("Your X kill count is: N"). From the first such message on, chat is
	 * the only thing that sets their KC: counting loot as well would be one ahead, or a whole raid ahead when the
	 * chest is opened long after the completion message.
	 */
	public Set<String> kcFromChat = ConcurrentHashMap.newKeySet();

	private transient Filepath file;
	/** set when the file on disk could not be read and was moved aside to this name (the plugin tells the player) */
	private transient Filepath setAside;
	private final transient AtomicBoolean dirty = new AtomicBoolean();

	/**
	 * Read the ledger at {@code file}, or start an empty one if there is none. A file that exists but can't be read is
	 * never overwritten: it is renamed to {@code *.corrupt-<time>} first, so the player's progress can be recovered.
	 */
	public static Ledger load(Gson gson, Filepath file)
	{
		Ledger l = null;
		Filepath setAside = null;
		if (file.exists())
		{
			try (Reader r = file.openBufferedReader())
			{
				l = gson.fromJson(r, Ledger.class);
				if (l != null)
				{
					l.normalize();
				}
			}
			catch (Exception e)
			{
				log.warn("could not read ledger {}", file, e);
				l = null;
			}
			if (l == null)
			{
				setAside = file.getParent().joinSegment(file.getFileName() + ".corrupt-" + new SimpleDateFormat("yyyyMMdd_HHmmss").format(new Date()));
				try
				{
					file.moveTo(setAside);
				}
				catch (IOException e)
				{
					// can't move it out of the way: refuse to save over it this session
					log.warn("could not set aside unreadable ledger {}", file, e);
					Ledger readOnly = new Ledger();
					readOnly.setAside = file;
					return readOnly;
				}
			}
		}
		if (l == null)
		{
			l = new Ledger();
		}
		l.file = file;
		l.setAside = setAside;
		return l;
	}

	/**
	 * Gson builds whatever it likes for interface-typed fields, and a hand-edited file may hold nulls: re-home
	 * everything in concurrent collections, dropping nulls, with combat task titles lower-cased for lookup.
	 */
	private void normalize()
	{
		ConcurrentMap<Integer, Entry> u = new ConcurrentHashMap<>();
		if (unlocks != null)
		{
			unlocks.forEach((k, v) ->
			{
				if (k != null && v != null)
				{
					u.put(k, v);
				}
			});
		}
		unlocks = u;
		ConcurrentMap<String, Integer> k = new ConcurrentHashMap<>();
		if (kc != null)
		{
			kc.forEach((key, v) ->
			{
				if (key != null && v != null)
				{
					k.put(key, v);
				}
			});
		}
		kc = k;
		manualComplete = concurrentSet(manualComplete, false);
		backlog = concurrentSet(backlog, false);
		caDone = concurrentSet(caDone, true);   // keys: older files hold raw titles
		kcFromChat = concurrentSet(kcFromChat, false);
	}

	private static Set<String> concurrentSet(Set<String> s, boolean lowerCase)
	{
		Set<String> out = ConcurrentHashMap.newKeySet();
		if (s != null)
		{
			for (String x : s)
			{
				if (x != null)
				{
					out.add(lowerCase ? caKey(x) : x);
				}
			}
		}
		return out;
	}

	/** Note a change that hasn't been written yet. */
	public void markDirty()
	{
		dirty.set(true);
	}

	public boolean isDirty()
	{
		return dirty.get();
	}

	/**
	 * Write the ledger if it has unsaved changes.
	 *
	 * @return false if a write was needed and failed (the ledger stays dirty)
	 */
	public synchronized boolean saveIfDirty(Gson gson)
	{
		if (!dirty.getAndSet(false))
		{
			return true;
		}
		if (save(gson))
		{
			return true;
		}
		dirty.set(true);
		return false;
	}

	/**
	 * Write atomically (own temp file + rename). Synchronized, so a scheduled save and a flush on logout can't
	 * interleave; a client-thread write that lands mid-save is picked up by the next one.
	 *
	 * @return false if the write failed
	 */
	public synchronized boolean save(Gson gson)
	{
		if (file == null)
		{
			return true;   // nothing to save to (placeholder before login, or a file we refused to overwrite)
		}
		Filepath tmp = null;
		try
		{
			Filepath parent = file.getParent();
			parent.createDirectories();
			tmp = parent.createTempFile(file.getFileName(), ".tmp");
			try (Writer w = tmp.openBufferedWriter())
			{
				gson.toJson(this, w);
			}
			try
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			return true;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("could not save ledger {}", file, e);
			if (tmp != null)
			{
				try
				{
					tmp.deleteIfExists();
				}
				catch (IOException ignored)
				{
				}
			}
			return false;
		}
	}

	/**
	 * Delete the file and detach this ledger from it, under the save lock, so a save already under way can't write
	 * the file back afterwards (!bmreset).
	 *
	 * @return false if the file exists and couldn't be deleted
	 */
	public synchronized boolean discard()
	{
		if (file != null)
		{
			try
			{
				file.deleteIfExists();
			}
			catch (IOException e)
			{
				log.warn("could not delete ledger {}", file, e);
				return false;
			}
		}
		file = null;
		dirty.set(false);
		return true;
	}

	public Filepath getFile()
	{
		return file;
	}

	/** Where an unreadable ledger file was moved to (or the file itself, if it couldn't be moved), else null. */
	public Filepath getSetAside()
	{
		return setAside;
	}

	public boolean isUnlocked(int itemId)
	{
		return unlocks.containsKey(itemId);
	}

	public int getKc(String key)
	{
		return kc.getOrDefault(key, 0);
	}

	/** The source's KC plus every raid mode counted separately for it ("Chambers of Xeric (Challenge Mode)"). */
	public int getKcAllModes(String source)
	{
		int total = 0;
		String modePrefix = source + " (";
		for (Map.Entry<String, Integer> e : kc.entrySet())
		{
			if (e.getKey().equals(source) || e.getKey().startsWith(modePrefix))
			{
				total += e.getValue();
			}
		}
		return total;
	}

	/** The game reported a KC in chat for {@code source} (stored under {@code key}: the source, or one of its raid modes). Authoritative from now on. */
	public void setKcFromChat(String source, String key, int n)
	{
		kcFromChat.add(source);
		kc.put(key, n);   // exact: it also corrects any over-count from before the first message
	}

	/** A kill (or chest) seen through loot: counted unless the game reports this source's KC itself. */
	public int countLoot(String source, int amount)
	{
		if (!kcFromChat.contains(source))
		{
			kc.merge(source, amount, Integer::sum);
		}
		return getKcAllModes(source);
	}

	public boolean isCaDone(String taskTitle)
	{
		return taskTitle != null && caDone.contains(caKey(taskTitle));
	}

	public boolean addCaDone(String taskTitle)
	{
		return caDone.add(caKey(taskTitle));
	}

	/**
	 * A combat task title as compared: the game's cache and the wiki-scraped ladder spell titles independently, so
	 * case, curly apostrophes, spacing and a trailing full stop are ignored.
	 */
	static String caKey(String title)
	{
		String t = title.toLowerCase(Locale.ROOT).replace('\u2019', '\'').replace('\u2018', '\'').replaceAll("\\s+", " ").trim();
		return t.endsWith(".") ? t.substring(0, t.length() - 1).trim() : t;
	}
}

/*
 * Bossman Mode: lock marks for bank items cut off at the top of the bank's scroll area.
 * BSD-2-Clause, see LICENSE.
 */
package com.bossman;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * RuneLite hands item overlays the bank items it drew, but leaves out a row cut off at the top of the scroll area
 * (rows cut off at the bottom are included). Without this those items look unlocked while half in view. Drawn once
 * per frame after the bank, with the same marks as {@link LockedItemOverlay}, clipped to the scroll area.
 */
public class LockedBankEdgeOverlay extends Overlay
{
	private final Client client;
	private final LockedItemOverlay marks;

	@Inject
	public LockedBankEdgeOverlay(Client client, LockedItemOverlay marks)
	{
		this.client = client;
		this.marks = marks;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		drawAfterInterface(InterfaceID.BANKMAIN);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.isHidden())
		{
			return null;
		}
		Widget[] children = items.getDynamicChildren();
		if (children == null)
		{
			return null;
		}
		Rectangle view = items.getBounds();
		Shape clip = graphics.getClip();
		graphics.clip(view);
		for (Widget w : children)
		{
			Rectangle b = w.getBounds();
			if (w.getItemId() > 0 && !w.isSelfHidden() && b.y < view.y && b.y + b.height > view.y)
			{
				marks.drawMarks(graphics, w.getItemId(), b);
			}
		}
		graphics.setClip(clip);
		return null;
	}
}

/*
 * Bossman Mode: dims locked items in the inventory, bank and equipment, marks free (tool/access) items, and marks
 * items unlocked only while the quest that needs them is in progress.
 * BSD-2-Clause, see LICENSE.
 */
package com.bossman;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;

@Singleton   // LockedBankEdgeOverlay draws with this same instance
public class LockedItemOverlay extends WidgetItemOverlay
{
	private static final Color DIM = new Color(0, 0, 0, 150);
	private static final Color LOCK = new Color(220, 60, 60, 230);
	private static final Color TOOL = new Color(90, 200, 120, 230);
	private static final Color ACCESS = new Color(90, 160, 230, 230);
	private static final Color BOND = new Color(230, 200, 90, 230);
	private static final int QUEST_ICON_SIZE = 10;

	private final BossmanModePlugin plugin;
	private final BossmanModeConfig config;
	private final ItemManager itemManager;
	private final BufferedImage questIcon;

	@Inject
	public LockedItemOverlay(BossmanModePlugin plugin, BossmanModeConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		questIcon = ImageUtil.resizeImage(ImageUtil.loadImageResource(LockedItemOverlay.class, "/bossman/quest_icon.png"),
			QUEST_ICON_SIZE, QUEST_ICON_SIZE);
		showOnInventory();
		showOnBank();
		showOnEquipment();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		Rectangle b = widgetItem.getCanvasBounds();
		if (b != null)
		{
			drawMarks(graphics, itemId, b);
		}
	}

	/**
	 * Dim + lock marker on a locked item, the quest icon on an item a started quest unlocks, or the free-item marker;
	 * shared with {@link LockedBankEdgeOverlay}.
	 */
	void drawMarks(Graphics2D graphics, int itemId, Rectangle b)
	{
		if (itemId <= 1 || itemId == ItemID.BANK_FILLER)
		{
			return;
		}
		LadderRules rules = plugin.getRules();
		if (rules.isAllowed(itemId))
		{
			if (rules.isQuestItemOnly(itemId))
			{
				// locks again when the quest is done, so it is marked whenever locked items are
				if (config.dimLocked())
				{
					graphics.drawImage(questIcon, b.x + b.width - QUEST_ICON_SIZE, b.y + b.height - QUEST_ICON_SIZE, null);
				}
				return;
			}
			if (config.markFree())
			{
				FreeKind kind = rules.freeKind(itemId);
				if (kind != null)
				{
					graphics.setColor(markerColor(kind));
					graphics.fillRect(b.x + b.width - 5, b.y + b.height - 5, 4, 4);
				}
			}
			return;
		}
		if (!config.dimLocked())
		{
			return;
		}
		if (!isPlaceholder(itemId))
		{
			// the game already greys a placeholder out; it only needs the lock marker
			graphics.setColor(DIM);
			graphics.fillRect(b.x, b.y, b.width, b.height);
		}
		// small padlock-ish marker in the bottom-right corner, clear of the stack count drawn top-left
		graphics.setColor(LOCK);
		int lx = b.x + b.width - 9;
		int ly = b.y + b.height - 8;
		graphics.fillRect(lx, ly, 7, 6);
		graphics.drawRect(lx + 1, ly - 3, 4, 4);
	}

	private static Color markerColor(FreeKind kind)
	{
		switch (kind)
		{
			case TOOL:
				return TOOL;
			case BOND:
				return BOND;
			default:
				return ACCESS;   // access gear, slayer tools, boss area craftables: all only get you to (or through) a boss
		}
	}

	private boolean isPlaceholder(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp != null && comp.getPlaceholderTemplateId() != -1;
	}
}

/*
 * Bossman Mode: which menu options a locked item loses. No client state, so it is tested in MenuRulesTest.
 */
package com.bossman;

import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import net.runelite.client.util.Text;

final class MenuRules
{
	private MenuRules()
	{
	}

	/**
	 * Whether a locked item's menu option should be removed: 'Offer' on the GE (no selling), 'Buy' in shops (exactly
	 * "Buy", "Buy 10", "Buy-X"), and the configured use-actions. Everything else (Examine, Drop, Deposit, ...)
	 * stays unless the player adds it to the blocked actions.
	 */
	static boolean strips(String option, boolean restrictGeSell, boolean restrictShops, boolean blockActions, Set<String> blockedActions)
	{
		if (option == null)
		{
			return false;
		}
		if ("Offer".equals(option))
		{
			return restrictGeSell;
		}
		if (option.equals("Buy") || option.startsWith("Buy ") || option.startsWith("Buy-"))
		{
			return restrictShops;
		}
		return blockActions && blockedActions.contains(option.toLowerCase(Locale.ROOT));
	}

	/** An item's deposit option at a bank or deposit box, the remembered Deposit-X amount ("Deposit-14") included. */
	static boolean isDeposit(String option)
	{
		return option != null && option.startsWith("Deposit-");
	}

	/** A bank or deposit box button that puts away everything carried or worn. */
	static boolean isDepositAll(String option)
	{
		return "Deposit inventory".equals(option) || "Deposit worn items".equals(option);
	}

	/** A comma-separated config list, each entry through Text.standardize (blanks dropped). */
	static Set<String> parseList(String csv)
	{
		Set<String> out = new HashSet<>();
		if (csv != null)
		{
			for (String s : csv.split(","))
			{
				String t = Text.standardize(s);
				if (!t.isEmpty())
				{
					out.add(t);
				}
			}
		}
		return out;
	}
}

/*
 * Bossman Mode: thousands separators for the numbers the panel, banner and chat show.
 */
package com.bossman;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class Numbers
{
	/** a run of four or more digits that isn't already part of a separated or decimal number */
	private static final Pattern LONG_NUMBER = Pattern.compile("(?<![\\d.,])\\d{4,}(?![\\d,])");

	private Numbers()
	{
	}

	static String format(long n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}

	/** Drop rates and notes from the bundled data are text ("1/5000"): separate every long number in it. */
	static String withCommas(String text)
	{
		if (text == null)
		{
			return null;
		}
		Matcher m = LONG_NUMBER.matcher(text);
		StringBuffer out = new StringBuffer();
		while (m.find())
		{
			m.appendReplacement(out, format(Long.parseLong(m.group())));
		}
		m.appendTail(out);
		return out.toString();
	}
}

/*
 * Bossman Mode: which inventory gains are completion rewards (receipt rules). No client state, so it is tested in
 * ReceiptDetectorTest; the plugin feeds it inventory and equipment counts.
 */
package com.bossman;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.IntPredicate;

final class ReceiptDetector
{
	/** a rule's companion items (Tokkul) count when gained this many ticks after the rule's own item */
	static final int COMPANION_TICKS = 5;

	/** An item to unlock, and the rule it unlocks under. */
	static final class Receipt
	{
		final int itemId;
		final BossmanData.ReceiptRule rule;

		Receipt(int itemId, BossmanData.ReceiptRule rule)
		{
			this.itemId = itemId;
			this.rule = rule;
		}
	}

	private ReceiptDetector()
	{
	}

	/**
	 * Items gained between two inventories, not counting ones that just came off the player (unequipped).
	 */
	static List<Integer> gained(Map<Integer, Integer> before, Map<Integer, Integer> now,
		Map<Integer, Integer> equipBefore, Map<Integer, Integer> equipNow)
	{
		List<Integer> out = new ArrayList<>();
		for (Map.Entry<Integer, Integer> en : now.entrySet())
		{
			int id = en.getKey();
			int unequipped = Math.max(0, equipBefore.getOrDefault(id, 0) - equipNow.getOrDefault(id, 0));
			if (en.getValue() > before.getOrDefault(id, 0) + unequipped)
			{
				out.add(id);
			}
		}
		return out;
	}

	/**
	 * The gained items that unlock under a rule. A rule's own items come first, so a companion gained in the same
	 * change (or within {@link #COMPANION_TICKS}) sees the match.
	 *
	 * @param lastMatch tick each rule last matched; updated here
	 * @param allowed   items already usable (not unlocked again)
	 */
	static List<Receipt> detect(List<Integer> gained, int region, int tick, List<BossmanData.ReceiptRule> rules,
		Map<String, Integer> lastMatch, IntPredicate allowed)
	{
		List<Receipt> out = new ArrayList<>();
		for (int id : gained)
		{
			for (BossmanData.ReceiptRule rule : rules)
			{
				if (rule.matches(id, region))
				{
					lastMatch.put(rule.name, tick);
					if (!allowed.test(id))
					{
						out.add(new Receipt(id, rule));
					}
					break;
				}
			}
		}
		for (int id : gained)
		{
			if (allowed.test(id) || out.stream().anyMatch(r -> r.itemId == id))
			{
				continue;
			}
			for (BossmanData.ReceiptRule rule : rules)
			{
				Integer at = lastMatch.get(rule.name);
				if (rule.companions != null && rule.companions.contains(id) && at != null && tick - at <= COMPANION_TICKS)
				{
					out.add(new Receipt(id, rule));
					break;
				}
			}
		}
		return out;
	}
}

