import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageCapture;

/**
 * The "item unlocked" banner at the top of the screen, captioned with the source boss and KC. Items unlocked by the
 * same loot (one chest, one kill) share a banner: "+N more" rather than a five-second banner each. It waits while the
 * game's own popup (a collection log entry, a combat task) holds the same spot.
 */
public class UnlockOverlay extends Overlay
{
	private static final long DISPLAY_MS = 5000;
	/** a frame gap longer than this (a loading screen, the client minimised) doesn't count as the banner being seen */
	private static final long MAX_FRAME_GAP_MS = 100;
	/** the banner slides down this far when it appears */
	private static final int SLIDE = 20;
	private static final int CAPTION_GAP = 4;
	private static final Color CAPTION_BG = new Color(0, 0, 0, 170);
	private static final Color CAPTION_FG = new Color(255, 200, 80);

	private static class Banner
	{
		final int itemId;
		final String caption;
		final int tick;
		int more;

		Banner(int itemId, String caption, int tick)
		{
			this.itemId = itemId;
			this.caption = caption;
			this.tick = tick;
		}

		String text()
		{
			String c = caption == null ? "" : caption;
			return more == 0 ? c : c + (c.isEmpty() ? "" : " ") + "(+" + more + " more)";
		}
	}

	private final Client client;
	private final BossmanModePlugin plugin;
	private final Deque<Banner> queue = new ArrayDeque<>();
	private Banner current;
	/** how long the current banner has actually been on screen */
	private long shownMs;
	private long lastFrame;
	private boolean firstFrame;
	private int slide;
	/** the game's popup hid the banner last frame: slide it back in when the popup goes */
	private boolean waiting;
	private boolean screenshotUnlock;
	private boolean includeFrame;
	private Font captionFont;

	@Inject private ItemManager itemManager;
	@Inject private ImageCapture imageCapture;

	@Inject
	public UnlockOverlay(Client client, BossmanModePlugin plugin)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);   // over raid reward chests and the like
	}

	/** Queue a banner; an unlock from the same loot as the last one queued joins it. Client thread. */
	public void addItemUnlock(int itemId, String caption)
	{
		int tick = client.getTickCount();
		synchronized (queue)
		{
			Banner last = queue.peekLast();
			if (last != null && last.tick == tick && Objects.equals(last.caption, caption))
			{
				last.more++;
				return;
			}
			queue.add(new Banner(itemId, caption, tick));
		}
	}

	/** Drop the banner showing and anything queued (shutdown, logout, world hop). */
	public void clear()
	{
		synchronized (queue)
		{
			queue.clear();
			current = null;
		}
	}

	public void updateScreenshotUnlock(boolean doScreenshotUnlock, boolean doIncludeFrame)
	{
		screenshotUnlock = doScreenshotUnlock;
		includeFrame = doIncludeFrame;
	}

	/** Save a screenshot of the next frame to the "Bossman Unlocks" folder. */
	public void screenshot(String fileName)
	{
		imageCapture.takeScreenshot("Bossman Unlocks", fileName, includeFrame, false, false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		BufferedImage banner = plugin.getUnlockImage();
		long now = System.currentTimeMillis();
		if (client.getGameState() != GameState.LOGGED_IN || banner == null)
		{
			lastFrame = 0;   // time away isn't time shown
			return null;
		}
		if (gamePopupShowing())
		{
			lastFrame = 0;
			waiting = true;
			return null;
		}
		Banner b;
		synchronized (queue)
		{
			if (current == null)
			{
				current = queue.poll();
				if (current == null)
				{
					return null;
				}
				shownMs = 0;
				slide = -SLIDE;
				firstFrame = true;
				lastFrame = 0;
			}
			b = current;
		}
		if (waiting)
		{
			waiting = false;
			slide = -SLIDE;
		}

		if (captionFont == null)
		{
			captionFont = graphics.getFont().deriveFont(Font.BOLD, 11f);
		}
		FontMetrics fm = graphics.getFontMetrics(captionFont);
		String text = b.text();
		int w = Math.max(banner.getWidth(), text.isEmpty() ? 0 : fm.stringWidth(text) + 10);
		int h = banner.getHeight() + (text.isEmpty() ? 0 : CAPTION_GAP + fm.getHeight() + 4);
		if (firstFrame)
		{
			// the overlay is placed using last frame's size: report the size once before drawing, so the banner
			// appears centred instead of hanging off to one side for a frame
			firstFrame = false;
			return new Dimension(w, h);
		}

		int bx = (w - banner.getWidth()) / 2;
		graphics.drawImage(banner, bx, slide, null);
		graphics.drawImage(itemManager.getImage(b.itemId, 1, false), bx + 12, slide + 7, null);
		if (!text.isEmpty())
		{
			Font old = graphics.getFont();
			graphics.setFont(captionFont);
			int tw = fm.stringWidth(text);
			int x = (w - tw) / 2;
			int y = slide + banner.getHeight() + CAPTION_GAP + fm.getAscent() + 2;
			graphics.setColor(CAPTION_BG);
			graphics.fillRoundRect(x - 5, y - fm.getAscent() - 2, tw + 10, fm.getHeight() + 4, 6, 6);
			graphics.setColor(CAPTION_FG);
			graphics.drawString(text, x, y);
			graphics.setFont(old);
		}

		if (slide < 0)
		{
			slide++;
		}
		if (lastFrame != 0)
		{
			shownMs += Math.min(now - lastFrame, MAX_FRAME_GAP_MS);
		}
		lastFrame = now;
		if (shownMs > DISPLAY_MS)
		{
			if (screenshotUnlock)
			{
				screenshot("ItemUnlocked " + itemManager.getItemComposition(b.itemId).getMembersName() + " ");
			}
			synchronized (queue)
			{
				if (current == b)
				{
					current = null;
				}
			}
		}
		return new Dimension(w, h);
	}

	private boolean gamePopupShowing()
	{
		Widget popup = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
		return popup != null && !popup.isHidden();
	}
}

package com.bossman;

import java.util.Arrays;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import org.junit.Test;
import static org.junit.Assert.*;

public class ActiveQuestsTest
{
	private static ActiveQuests foes()
	{
		Map<String, BossmanData.QuestNeeds> data = new HashMap<>();
		BossmanData.QuestNeeds ds1 = new BossmanData.QuestNeeds();
		ds1.npcs = Arrays.asList("Elvarg", "Melzar the Mad");
		BossmanData.ItemRef mindBomb = new BossmanData.ItemRef();
		mindBomb.id = 1907;
		ds1.items = Arrays.asList(mindBomb);
		data.put("DRAGON_SLAYER_I", ds1);
		BossmanData.QuestNeeds renamed = new BossmanData.QuestNeeds();
		renamed.npcs = Arrays.asList("Nobody");
		data.put("A_QUEST_RUNELITE_RENAMED", renamed);
		return new ActiveQuests(data);
	}

	@Test
	public void aStartedQuestOpensItsFoesAndItems()
	{
		ActiveQuests f = foes();
		f.refresh(q -> QuestState.IN_PROGRESS);
		assertTrue(f.npcs().contains("elvarg"));
		assertTrue(f.npcs().contains("melzar the mad"));
		assertTrue(f.itemIds().contains(1907));
	}

	@Test
	public void unstartedAndFinishedQuestsDont()
	{
		ActiveQuests f = foes();
		f.refresh(q -> QuestState.NOT_STARTED);
		assertTrue(f.npcs().isEmpty());
		f.refresh(q -> QuestState.FINISHED);
		assertTrue(f.npcs().isEmpty());
		assertTrue(f.itemIds().isEmpty());
	}

	@Test
	public void aFinishedQuestIsNotReadAgainUntilReset()
	{
		ActiveQuests f = foes();
		Map<Quest, AtomicInteger> reads = new EnumMap<>(Quest.class);
		f.refresh(q ->
		{
			reads.computeIfAbsent(q, k -> new AtomicInteger()).incrementAndGet();
			return QuestState.FINISHED;
		});
		f.refresh(q ->
		{
			reads.computeIfAbsent(q, k -> new AtomicInteger()).incrementAndGet();
			return QuestState.IN_PROGRESS;
		});
		assertEquals(1, reads.get(Quest.DRAGON_SLAYER_I).get());
		assertTrue(f.npcs().isEmpty());
		f.reset();
		f.refresh(q -> QuestState.IN_PROGRESS);
		assertTrue(f.npcs().contains("elvarg"));
	}
}

package com.bossman;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.Set;
import net.runelite.client.util.Text;
import org.junit.Test;
import static org.junit.Assert.*;

public class AttackRulesTest
{
	private static final BossmanData DATA = load();
	private static final Set<String> NONE = Collections.emptySet();
	private static final int NOWHERE = -1;
	private static final int LUMBRIDGE = 12850;

	private static BossmanData load()
	{
		BossmanData d = new BossmanData();
		d.load(new Gson());
		return d;
	}

	private static AttackRules.Reason reason(String inGameName)
	{
		return AttackRules.reason(-1, Text.standardize(inGameName), NOWHERE, false, NONE, NONE, DATA);
	}

	private static AttackRules.Reason reasonIn(int region)
	{
		return AttackRules.reason(-1, "snakeling", region, false, NONE, NONE, DATA);
	}

	@Test
	public void attackingAndCombatSpellsAreCombat()
	{
		assertTrue(AttackRules.isCombatOption("Attack", "Goblin  (level-2)"));
		assertTrue(AttackRules.isCombatOption("Fight", "Kolodion"));
		assertTrue(AttackRules.isCombatOption("Cast", "Wind Strike -> Goblin  (level-2)"));
		assertTrue(AttackRules.isCombatOption("Cast", "Ice Barrage -> Goblin  (level-2)"));
	}

	@Test
	public void talkingTradingAndNonCombatSpellsAreNot()
	{
		assertFalse(AttackRules.isCombatOption("Talk-to", "Goblin"));
		assertFalse(AttackRules.isCombatOption("Pickpocket", "Man"));
		assertFalse(AttackRules.isCombatOption("Use", "Bucket -> Cow"));
		assertFalse(AttackRules.isCombatOption("Cast", "Monster Examine -> Goblin  (level-2)"));
		assertFalse(AttackRules.isCombatOption("Cast", "Dark Lure -> Goblin  (level-2)"));
		assertFalse(AttackRules.isCombatOption("Cast", null));
		assertFalse(AttackRules.isCombatOption(null, null));
	}

	@Test
	public void bossesMayBeFoughtAndOrdinaryMonstersMayNot()
	{
		assertEquals(AttackRules.Reason.BOSS, reason("Zulrah"));
		assertEquals(AttackRules.Reason.BOSS, reason("Brutus"));
		assertEquals(AttackRules.Reason.BOSS, reason("<col=ffff00>Vorkath"));
		assertNull(reason("Goblin"));
		assertNull(reason("Cow"));
	}

	@Test
	public void namesMatchWithTagsAndNonBreakingSpaces()
	{
		assertEquals(AttackRules.Reason.BOSS_ACCESS, reason("<col=ff0000>Revenant imp</col>"));
	}

	@Test
	public void everythingInABossArenaMayBeFought()
	{
		int[] arenas = {
			11347,   // God Wars Dungeon (Bandos side, followers for KC)
			7512,    // the Gauntlet
			9551,    // Fight Caves
			9043,    // Inferno
			7216,    // Fortis Colosseum
			13137,   // Chambers of Xeric
			12613,   // Theatre of Blood
			9007,    // Zulrah's shrine
			6556,    // Catacombs of Kourend (Skotizo's totem pieces)
		};
		for (int region : arenas)
		{
			assertEquals("region " + region, AttackRules.Reason.ARENA, reasonIn(region));
		}
		assertNull("Lumbridge", reasonIn(LUMBRIDGE));
		assertNull("Varrock", reasonIn(12853));
	}

	@Test
	public void monstersThatDropABossKeyMayBeFought()
	{
		assertEquals(AttackRules.Reason.BOSS_ACCESS, reason("Hill Giant"));
		assertEquals(AttackRules.Reason.BOSS_ACCESS, reason("Moss giant"));
		assertEquals(AttackRules.Reason.BOSS_ACCESS, reason("Revenant knight"));
		assertNull(reason("Cyclops"));   // drops no boss key, and opening it would free the Warriors' Guild
	}

	@Test
	public void fightAddsListedByIdMatchOnlyThoseIds()
	{
		int vetionHellhound = 6613;
		int myrequeHellhound = 5054;
		assertEquals(AttackRules.Reason.BOSS_ACCESS,
			AttackRules.reason(vetionHellhound, "skeleton hellhound", NOWHERE, false, NONE, NONE, DATA));
		assertNull(AttackRules.reason(myrequeHellhound, "skeleton hellhound", NOWHERE, false, NONE, NONE, DATA));
		assertEquals(AttackRules.Reason.BOSS_ACCESS,
			AttackRules.reason(12001, "spindel's spiderling", NOWHERE, false, NONE, NONE, DATA));
	}

	@Test
	public void slayerTaskQuestAndConfigOpenUpAMonster()
	{
		String goblin = "goblin";
		assertEquals(AttackRules.Reason.SLAYER_TASK, AttackRules.reason(-1, goblin, NOWHERE, true, NONE, NONE, DATA));
		assertEquals(AttackRules.Reason.QUEST,
			AttackRules.reason(-1, goblin, NOWHERE, false, Collections.singleton(goblin), NONE, DATA));
		assertEquals(AttackRules.Reason.EXTRA_ATTACKABLE,
			AttackRules.reason(-1, goblin, NOWHERE, false, NONE, Collections.singleton(goblin), DATA));
		assertEquals(AttackRules.Reason.EXTRA_ATTACKABLE,
			AttackRules.reason(3029, goblin, NOWHERE, false, NONE, Collections.singleton("3029"), DATA));
	}

	@Test
	public void tutorialIslandRatsMayBeFoughtUntilTheTutorialIsDone()
	{
		assertFalse(AttackRules.tutorialDone(AttackRules.TUTORIAL_DONE - 1));
		assertTrue(AttackRules.tutorialDone(AttackRules.TUTORIAL_DONE));
	}
}

package com.bossman;

import com.google.gson.Gson;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.*;

public class BossmanDataTest
{
	private static BossmanData load()
	{
		BossmanData d = new BossmanData();
		d.load(new Gson());
		return d;
	}

	@Test
	public void bundledDataLoads()
	{
		BossmanData d = load();
		assertTrue(d.getFreeItems().size() > 50);
		assertTrue(d.isNpcSource("Brutus"));
		assertTrue(d.isNpcSource("calvar'ion"));
		assertFalse(d.isNpcSource("Hill Giant"));
		assertTrue(d.isEventSource("Barrows"));
		assertFalse(d.isEventSource("Brimstone Chest"));
		assertEquals(67, d.orderedRungs().size());
		assertEquals("Brutus", d.orderedRungs().get(0).boss);
		assertEquals("The Mimic", d.orderedRungs().get(5).boss);
		assertTrue(d.orderedRungs().get(5).isFirstKillOnly());
		assertEquals(69, d.browsableRungs().size());
		assertEquals(d.orderedRungs(), d.browsableRungs().subList(0, 67));
		assertEquals("Tempoross", d.browsableRungs().get(67).boss);
		assertEquals("Wintertodt", d.browsableRungs().get(68).boss);
		assertEquals(1351, (int) d.getTools().groups.get("general").get(0).id); // bronze axe
	}

	@Test
	public void chatNamesFindTheirSource()
	{
		BossmanData d = load();
		assertEquals("The Nightmare", d.canonicalSource("Nightmare"));
		assertEquals("Phosani's Nightmare", d.canonicalSource("Phosani's Nightmare"));
		assertEquals("Deranged archaeologist", d.canonicalSource("Deranged Archaeologist"));
		assertEquals("Crystalline Hunllef", d.canonicalSource("Gauntlet"));
		assertEquals("Corrupted Hunllef", d.canonicalSource("Corrupted Gauntlet"));
		assertEquals("Barrows", d.canonicalSource("barrows"));
		assertNull(d.canonicalSource("Hill Giant"));
	}

	@Test
	public void extraSourcesAddWithoutDroppingBundledOnes()
	{
		BossmanData d = load();
		d.setExtraSources("Some New Boss, ");
		assertTrue(d.isNpcSource("some new boss"));
		assertTrue(d.isNpcSource("Brutus"));
		d.setExtraSources("");
		assertFalse(d.isNpcSource("Some New Boss"));
	}

	@Test
	public void everyRungSourceIsSomethingThePluginCounts()
	{
		BossmanData d = load();
		Set<String> receiptNames = new HashSet<>();
		for (BossmanData.ReceiptRule r : d.getSources().receiptRules)
		{
			receiptNames.add(r.name);
		}
		for (BossmanData.Rung r : d.getLadder().rungs)
		{
			for (String s : r.sources)
			{
				assertTrue(r.boss + ": source " + s + " is neither an NPC, an event nor a receipt rule",
					d.canonicalSource(s) != null || receiptNames.contains(s));
			}
			if (r.kcSource != null)
			{
				assertTrue(r.boss + ": kc_source is not one of its sources", r.sources.contains(r.kcSource));
			}
		}
	}

	@Test
	public void kcIsStoredUnderTheSpellingTheLadderUses()
	{
		// KC is keyed by the bundled NPC spelling; a ladder source spelled differently read 0 forever
		BossmanData d = load();
		for (BossmanData.Rung r : d.getLadder().rungs)
		{
			for (String s : r.sources)
			{
				String c = d.canonicalNpcName(s);
				assertTrue(r.boss + ": " + s + " vs " + c, c == null || c.equals(s));
			}
		}
	}

	@Test
	public void everyLogItemCanBeUnlocked()
	{
		BossmanData d = load();
		for (BossmanData.Rung r : d.getLadder().rungs)
		{
			for (BossmanData.GatingItem g : r.log.gatingItems)
			{
				assertFalse(r.boss + ": " + g.item + " has no item id", g.ids.isEmpty());
			}
		}
	}

	@Test
	public void raidAndYamaRatesAreNotUniqueTableWeights()
	{
		// the scrape gives purple-table weights for raids ("Twisted bow 1/28") and "Always" for Yama's armour
		BossmanData d = load();
		for (BossmanData.Rung r : d.getLadder().rungs)
		{
			if (r.boss.contains("(raid)"))
			{
				for (BossmanData.GatingItem g : r.log.gatingItems)
				{
					assertNull(r.boss + ": " + g.item, g.denominator);
				}
				assertNull(r.boss, r.log.expectedKc);
			}
			if (r.boss.equals("Yama"))
			{
				for (BossmanData.GatingItem g : r.log.gatingItems)
