	@Test
	public void jarsGateOnlyWhenSwitchedOnAndAreToldApartFromPets()
	{
		BossmanData.Rung kraken = rung("Kraken");
		BossmanData.DebtItem jar = kraken.log.debtPetsJars.stream().filter(rules::isJar).findFirst().get();
		BossmanData.DebtItem pet = kraken.log.debtPetsJars.stream().filter(d -> !rules.isJar(d)).findFirst().get();
		assertFalse(rules.isDebtItemGating(jar));
		jarsGate = true;
		assertTrue(rules.isDebtItemGating(jar));
		assertFalse(rules.isDebtItemGating(pet));
	}

	@Test
	public void aPetIsOwedFromExactlyItsDebtKc()
	{
		BossmanData.Rung kbd = rung("King Black Dragon");
		BossmanData.DebtItem prince = kbd.log.debtPetsJars.get(0);
		ledger.setKcFromChat("King Black Dragon", "King Black Dragon", prince.debtAtKc - 1);
		assertFalse(rules.isDebtOwed(kbd, prince));
		ledger.setKcFromChat("King Black Dragon", "King Black Dragon", prince.debtAtKc);
		assertTrue(rules.isDebtOwed(kbd, prince));
		prince.debtAtKc = null;   // unknown rate: never owed
		assertFalse(rules.isDebtOwed(kbd, prince));
	}

	@Test
	public void aPetRecordedUnderAnotherIdCountsByName()
	{
		BossmanData.Rung kbd = rung("King Black Dragon");
		BossmanData.DebtItem prince = kbd.log.debtPetsJars.get(0);
		assertFalse(rules.isDebtItemUnlocked(prince));
		Ledger.Entry follower = new Ledger.Entry();
		follower.itemId = 99998;
		follower.name = "prince black dragon";
		ledger.unlocks.put(follower.itemId, follower);
		assertTrue(rules.isDebtItemUnlocked(prince));
	}

	@Test
	public void aRungCompletesWhenItsGatingItemsAreIn()
	{
		BossmanData.Rung kbd = rung("King Black Dragon");
		assertFalse(rules.isRungComplete(kbd));
		unlockAllGating(kbd);
		assertTrue(rules.isRungComplete(kbd));
	}

	@Test
	public void backloggedItemsStopGating()
	{
		BossmanData.Rung kbd = rung("King Black Dragon");
		unlockAllGating(kbd);
		BossmanData.GatingItem first = kbd.log.gatingItems.stream().filter(g -> !rules.isMeme(g)).findFirst().get();
		ledger.unlocks.remove(first.ids.get(0));
		assertFalse(rules.isRungComplete(kbd));
		ledger.backlog.add(LadderRules.backlogKey(kbd, first.item));
		assertTrue(rules.isRungComplete(kbd));
	}

	@Test
	public void optionalItemsNeverGate()
	{
		BossmanData.Rung cox = rung("Chambers of Xeric (raid)");
		BossmanData.GatingItem dust = cox.log.gatingItems.stream().filter(g -> g.item.equals("Metamorphic dust")).findFirst().get();
		assertTrue(rules.isMeme(dust));
		unlockAllGating(cox);
		assertTrue(rules.isRungComplete(cox));
	}

	@Test
	public void theMemeThresholdIsInclusive()
	{
		BossmanData.GatingItem g = new BossmanData.GatingItem();
		g.denominator = 5000;
		assertTrue(rules.isMeme(g));
		g.denominator = 4999;
		assertFalse(rules.isMeme(g));
	}

	@Test
	public void petsGateOnlyWhenSwitchedOn()
	{
		BossmanData.Rung kbd = rung("King Black Dragon");
		unlockAllGating(kbd);
		assertTrue(rules.isRungComplete(kbd));
		petsGate = true;
		assertFalse(rules.isRungComplete(kbd));
		assertEquals(rules.progress(kbd).need - 1, rules.progress(kbd).have);
	}

	@Test
	public void combatTasksCountTowardsProgressWhenTheyGate()
	{
		BossmanData.Rung kbd = rung("King Black Dragon");
		int items = rules.progress(kbd).need;
		caGate = true;
		assertEquals(items + kbd.ca.list.size(), rules.progress(kbd).need);
		assertFalse(kbd.ca.list.isEmpty());
		unlockAllGating(kbd);
		assertFalse(rules.isRungComplete(kbd));
		for (BossmanData.CaTask t : kbd.ca.list)
		{
			ledger.addCaDone(t.name.toUpperCase());   // matched case-insensitively
		}
		assertTrue(rules.isRungComplete(kbd));
	}

	@Test
	public void aFirstKillOnlyRungNeedsOneKill()
	{
		BossmanData.Rung mimic = rung("The Mimic");
		assertFalse(rules.isRungComplete(mimic));
		ledger.setKcFromChat("The Mimic", "The Mimic", 1);
		assertTrue(rules.isRungComplete(mimic));
	}

	@Test
	public void theMoonsKcIsTheChestAndEachMoonIsKeptApart()
	{
		BossmanData.Rung moons = rung("Blood Moon / Blue Moon / Eclipse Moon");
		ledger.countLoot("Lunar Chest", 1);
		ledger.setKcFromChat("Blood Moon", "Blood Moon", 3);
		ledger.setKcFromChat("Blue Moon", "Blue Moon", 2);
		assertEquals(1, rules.rungKc(moons));
		Map<String, Integer> by = rules.kcBySource(moons);
		assertEquals(Integer.valueOf(3), by.get("Blood Moon"));
		assertEquals(Integer.valueOf(2), by.get("Blue Moon"));
		assertEquals(Integer.valueOf(0), by.get("Eclipse Moon"));
	}

	@Test
	public void multiBossRungsWithoutAKcSourceSumTheirSources()
	{
		BossmanData.Rung dks = rung("Dagannoth Kings");
		ledger.countLoot("Dagannoth Rex", 2);
		ledger.countLoot("Dagannoth Prime", 1);
		assertEquals(3, rules.rungKc(dks));
	}

	@Test
	public void chatKcIsAuthoritative()
	{
		ledger.countLoot("Vorkath", 1);
		ledger.countLoot("Vorkath", 1);
		ledger.setKcFromChat("Vorkath", "Vorkath", 14);     // the game's own number replaces our count
		assertEquals(14, ledger.getKc("Vorkath"));
		assertEquals(14, ledger.countLoot("Vorkath", 1));   // and loot no longer adds to it
	}

	@Test
	public void raidModesAddUpToTheRaidsKc()
	{
		BossmanData.Rung cox = rung("Chambers of Xeric (raid)");
		ledger.setKcFromChat("Chambers of Xeric", "Chambers of Xeric", 10);
		ledger.setKcFromChat("Chambers of Xeric", "Chambers of Xeric (Challenge Mode)", 4);
		assertEquals(14, rules.rungKc(cox));
		assertEquals(14, ledger.countLoot("Chambers of Xeric", 1));   // the chest doesn't add a run on top
	}

	@Test
	public void aLadderSpellingThatDiffersStillFindsItsKc()
	{
		BossmanData.Rung r = new BossmanData.Rung();
		r.boss = "test";
		r.sources = Collections.singletonList("Deranged Archaeologist");
		ledger.countLoot("Deranged archaeologist", 1);
		assertEquals(1, rules.rungKc(r));
	}
}

package com.bossman;

import com.google.gson.Gson;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class LedgerTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private final Gson gson = new Gson();

	/** The plugin gets a Filepath from getPluginDirectory(); tests root one at a temporary folder. */
	private Filepath ledgerFile() throws Exception
	{
		return Filepath.Unchecked.getRooted(tmp.newFolder("standard-123").toPath()).joinSegment("bossman-mode-ledger.json");
	}

	private static File file(Filepath f)
	{
		return Filepath.Unchecked.getFile(f);
	}

	private static String read(Filepath f) throws Exception
	{
		return new String(Files.readAllBytes(file(f).toPath()), StandardCharsets.UTF_8);
	}

	private static void write(Filepath f, String text) throws Exception
	{
		Files.write(file(f).toPath(), text.getBytes(StandardCharsets.UTF_8));
	}

	@Test
	public void everyFieldSurvivesASaveAndLoad() throws Exception
	{
		Filepath f = ledgerFile();
		Ledger l = Ledger.load(gson, f);
		Ledger.Entry e = new Ledger.Entry();
		e.itemId = 4151;
		e.name = "Abyssal whip";
		e.kind = Ledger.KIND_DROP;
		e.source = "Abyssal Sire";
		e.kc = 12;
		l.unlocks.put(e.itemId, e);
		l.setKcFromChat("Chambers of Xeric", "Chambers of Xeric (Challenge Mode)", 4);
		l.countLoot("Vorkath", 1);
		l.manualComplete.add("Gemstone Crab");
		l.backlog.add("Vorkath|Draconic visage");
		l.addCaDone("Noxious Foe");
		assertTrue(l.save(gson));

		Ledger back = Ledger.load(gson, f);
		assertEquals("Abyssal whip", back.unlocks.get(4151).name);   // integer map keys come back as integers
		assertEquals(Integer.valueOf(12), back.unlocks.get(4151).kc);
		assertEquals(4, back.getKc("Chambers of Xeric (Challenge Mode)"));
		assertTrue(back.kcFromChat.contains("Chambers of Xeric"));
		assertEquals(1, back.getKc("Vorkath"));
		assertTrue(back.manualComplete.contains("Gemstone Crab"));
		assertTrue(back.backlog.contains("Vorkath|Draconic visage"));
		assertTrue(back.isCaDone("noxious foe"));
		assertNull(back.getSetAside());
	}

	@Test
	public void collectionsAreConcurrentAfterLoading() throws Exception
	{
		Filepath f = ledgerFile();
		write(f, "{\"unlocks\":{},\"kc\":{},\"backlog\":[\"a|b\"]}");
		Ledger l = Ledger.load(gson, f);
		assertTrue(l.unlocks instanceof ConcurrentHashMap);   // whatever Gson built
		assertTrue(l.kc instanceof ConcurrentHashMap);
		assertTrue(l.backlog.getClass().getName().contains("Concurrent"));
		assertNotNull(l.caDone);   // missing in the file: still usable
	}

	@Test
	public void aCorruptFileIsSetAsideNotOverwritten() throws Exception
	{
		Filepath f = ledgerFile();
		write(f, "{\"unlocks\": {");
		Ledger l = Ledger.load(gson, f);
		assertNotNull(l.getSetAside());
		assertEquals("{\"unlocks\": {", read(l.getSetAside()));   // the player's bytes are kept
		assertTrue(l.unlocks.isEmpty());
		l.markDirty();
		assertTrue(l.saveIfDirty(gson));
		assertTrue(f.exists());                                      // a fresh ledger saves next to it
		assertEquals("{\"unlocks\": {", read(l.getSetAside()));
	}

	@Test
	public void nullsInAHandEditedFileAreDropped() throws Exception
	{
		Filepath f = ledgerFile();
		write(f, "{\"backlog\":[null,\"a|b\"],\"caDone\":[null],\"kc\":{\"Vorkath\":null}}");
		Ledger l = Ledger.load(gson, f);
		assertNull(l.getSetAside());
		assertEquals(1, l.backlog.size());
		assertTrue(l.caDone.isEmpty());
		assertEquals(0, l.getKc("Vorkath"));
	}

	@Test
	public void aFileThatCantBeMovedAsideIsNeverWritten() throws Exception
	{
		File dir = tmp.newFolder("locked");
		Filepath f = Filepath.Unchecked.getRooted(dir.toPath()).joinSegment("bossman-mode-ledger.json");
		write(f, "not json");
		assertTrue(dir.setWritable(false));   // no rename possible in a read-only folder
		try
		{
			Ledger l = Ledger.load(gson, f);
			assertEquals(f, l.getSetAside());
			assertNull(l.getFile());
			l.markDirty();
			assertTrue(l.saveIfDirty(gson));  // a no-op...
			assertEquals("not json", read(f)); // ...that leaves the bytes alone
		}
		finally
		{
			dir.setWritable(true);
		}
	}

	@Test
	public void saveIfDirtyWritesOnlyWhenSomethingChanged() throws Exception
	{
		Filepath f = ledgerFile();
		Ledger l = Ledger.load(gson, f);
		assertTrue(l.saveIfDirty(gson));
		assertFalse(f.exists());
		l.markDirty();
		assertTrue(l.saveIfDirty(gson));
		assertTrue(f.exists());
		assertFalse(l.isDirty());
	}

	@Test
	public void discardDeletesAndDetaches() throws Exception
	{
		Filepath f = ledgerFile();
		Ledger l = Ledger.load(gson, f);
		assertTrue(l.save(gson));
		assertTrue(l.discard());
		assertFalse(f.exists());
		l.markDirty();
		assertTrue(l.saveIfDirty(gson));
		assertFalse(f.exists());   // a save after the reset can't bring the file back
	}

	@Test
	public void caTitlesMatchAcrossSpellings()
	{
		Ledger l = new Ledger();
		l.addCaDone("Whack-a-Mole");
		assertTrue(l.isCaDone("whack-a-mole."));
		l.addCaDone("Can’t Touch Me");
		assertTrue(l.isCaDone("Can't  touch me"));
	}
}

package com.bossman;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.*;

public class MenuRulesTest
{
	private static final Set<String> BLOCKED = new HashSet<>(Arrays.asList("wield", "wear", "eat", "drink"));

	private static boolean strips(String option)
	{
		return MenuRules.strips(option, true, true, true, BLOCKED);
	}

	@Test
	public void sellingAndBuyingAreBlocked()
	{
		assertTrue(strips("Offer"));
		assertTrue(strips("Buy"));
		assertTrue(strips("Buy 1"));
		assertTrue(strips("Buy 50"));
		assertTrue(strips("Buy-X"));
	}

	@Test
	public void configuredActionsAreBlockedWhateverTheirCase()
	{
		assertTrue(strips("Wield"));
		assertTrue(strips("Drink"));
	}

	@Test
	public void everyDepositOptionIsADeposit()
	{
		for (String o : new String[]{"Deposit-1", "Deposit-5", "Deposit-10", "Deposit-X", "Deposit-All", "Deposit-14"})
		{
			assertTrue(o, MenuRules.isDeposit(o));
		}
		assertFalse(MenuRules.isDeposit("Withdraw-1"));
		assertFalse(MenuRules.isDeposit("Deposit inventory"));
		assertTrue(MenuRules.isDepositAll("Deposit inventory"));
		assertTrue(MenuRules.isDepositAll("Deposit worn items"));
		assertFalse(MenuRules.isDepositAll("Deposit-All"));
	}

	@Test
	public void holdingAnItemIsNeverBlockedByDefault()
	{
		assertFalse(strips("Examine"));
		assertFalse(strips("Drop"));
		assertFalse(strips("Deposit-All"));
		assertFalse(strips("Buyer"));   // not a buy option
		assertFalse(strips(null));
	}

	@Test
	public void eachRestrictionHasItsOwnSwitch()
	{
		assertFalse(MenuRules.strips("Offer", false, true, true, BLOCKED));
		assertFalse(MenuRules.strips("Buy 1", true, false, true, BLOCKED));
		assertFalse(MenuRules.strips("Wield", true, true, false, BLOCKED));
	}

	@Test
	public void configListsAreTrimmedLowerCasedAndSkipBlanks()
	{
		assertEquals(new HashSet<>(Arrays.asList("hill giant", "3029")), MenuRules.parseList(" Hill Giant , 3029,"));
		assertTrue(MenuRules.parseList(null).isEmpty());
	}
}

package com.bossman;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class NumbersTest
{
	@Test
	public void numbersOfFourOrMoreDigitsGetCommas()
	{
		assertEquals("999", Numbers.format(999));
		assertEquals("1,054", Numbers.format(1054));
		assertEquals("10,000", Numbers.format(10000));
		assertEquals("1,210,421", Numbers.format(1210421));
	}

	@Test
	public void ratesAndNotesInTextGetCommas()
	{
		assertEquals("Drop Rate: 1/5,000 - expected by KC 5,000", Numbers.withCommas("Drop Rate: 1/5000 - expected by KC 5000"));
